  dplyr::filter(
    Amplifier != "0",
    !Adjective %in% c("many", "much")
  ) |&gt;
  dplyr::group_by(Adjective) |&gt;
  dplyr::mutate(AdjFreq = dplyr::n()) |&gt;
  dplyr::ungroup() |&gt;
  dplyr::mutate(Adjective = ifelse(AdjFreq &gt; 10, Adjective, "other")) |&gt;
  dplyr::filter(Adjective != "other") |&gt;
  dplyr::select(-AdjFreq)

