Pointwise Mutual Information (PMI) Collocations
PMI measures how much more likely two words are to appear together than if they occurred independently. A high PMI score indicates a strong, statistically unexpected association:
\[\text{PMI}(w_1, w_2) = \log_2\frac{P(w_1, w_2)}{P(w_1) \cdot P(w_2)}\]


Code
# Unigram counts (all words) per book for marginal probabilities
unigrams_all &lt;- books |&gt;
    tidytext::unnest_tokens(word, text) |&gt;
    dplyr::count(book, word, name = "n_word")

total_words &lt;- unigrams_all |&gt;
    dplyr::group_by(book) |&gt;
    dplyr::summarise(total = sum(n_word), .groups = "drop")

# Bigrams (including stop words) for joint probabilities
bigrams_raw &lt;- books |&gt;
    dplyr::group_by(book) |&gt;
    tidytext::unnest_tokens(bigram, text, token = "ngrams", n = 2) |&gt;
    dplyr::filter(!is.na(bigram)) |&gt;
    tidyr::separate(bigram, into = c("word1", "word2"), sep = " ") |&gt;
    dplyr::count(book, word1, word2, name = "n_bigram", sort = TRUE) |&gt;
    dplyr::ungroup()

# Compute PMI
pmi_df &lt;- bigrams_raw |&gt;
    dplyr::left_join(total_words, by = "book") |&gt;
    dplyr::left_join(unigrams_all |&gt; dplyr::rename(word1 = word, n_w1 = n_word),
                     by = c("book", "word1")) |&gt;
    dplyr::left_join(unigrams_all |&gt; dplyr::rename(word2 = word, n_w2 = n_word),
                     by = c("book", "word2")) |&gt;
    dplyr::filter(n_bigram &gt;= 5, !is.na(n_w1), !is.na(n_w2)) |&gt;
    dplyr::mutate(
        pmi = log2((n_bigram / total) / ((n_w1 / total) * (n_w2 / total)))
    ) |&gt;
    dplyr::filter(
        !word1 %in% tidytext::stop_words$word,
        !word2 %in% tidytext::stop_words$word,
        stringr::str_detect(word1, "^[a-z]+$"),
        stringr::str_detect(word2, "^[a-z]+$")
    ) |&gt;
    dplyr::arrange(desc(pmi))




Code
pmi_df |&gt;
    dplyr::mutate(bigram = paste(word1, word2)) |&gt;
    dplyr::group_by(book) |&gt;
    dplyr::slice_max(pmi, n = 12) |&gt;
    dplyr::ungroup() |&gt;
    ggplot(aes(pmi, forcats::fct_reorder(bigram, pmi), fill = book)) +
    geom_col(show.legend = FALSE) +
    facet_wrap(~ book, ncol = 2, scales = "free") +
    theme_bw() +
    labs(x = "Pointwise Mutual Information (PMI)", y = NULL,
