Preparing the Function-Word Matrix
We use the 200 most frequent words in the combined corpus as features — a standard approach in stylometry that captures predominantly function words.


Code
set.seed(2026)

# Sample equal-length chunks: 3 chunks of 1000 lines per book
chunk_size &lt;- 1000

books_chunked &lt;- books |&gt;
    dplyr::group_by(book) |&gt;
    dplyr::mutate(chunk_id = ceiling(dplyr::row_number() / chunk_size)) |&gt;
    dplyr::filter(chunk_id &lt;= 3) |&gt;          # keep at most 3 chunks per book
    dplyr::mutate(
        doc_id = paste0(book, "_chunk", chunk_id)
    ) |&gt;
    dplyr::ungroup()

# Build DFM with relative term frequencies
stylo_dfm &lt;- books_chunked |&gt;
    dplyr::group_by(doc_id) |&gt;
    dplyr::summarise(text = paste(text, collapse = " "), .groups = "drop") |&gt;
    quanteda::corpus(text_field = "text", docid_field = "doc_id") |&gt;
    quanteda::tokens(remove_punct = TRUE, remove_numbers = TRUE) |&gt;
    quanteda::tokens_tolower() |&gt;
    quanteda::dfm() |&gt;
    quanteda::dfm_weight(scheme = "prop")   # relative frequencies

# Keep top 200 features (mostly function words)
stylo_dfm_top &lt;- quanteda::dfm_select(
    stylo_dfm,
    pattern = quanteda::featnames(
        quanteda::dfm_sort(stylo_dfm, decreasing = TRUE)
    )[1:200]
)

Creating word-level co-occurrence pairs
We tokenise the sentences into individual words and cross-join German and English tokens within each sentence. Each row of the result represents a German–English word pair that co-occurred in the same sentence translation unit.


Code
# tokenise German sentences
german_tokens &lt;- germantb |&gt;
  tidytext::unnest_tokens(word, german)

# join English sentences by sentence id, then tokenise English
transtb &lt;- german_tokens |&gt;
  dplyr::left_join(englishtb, by = "sentence") |&gt;
  tidytext::unnest_tokens(trans, english) |&gt;
  dplyr::rename(german = word, english = trans) |&gt;
  dplyr::select(german, english) |&gt;
  dplyr::mutate(
    german  = factor(german),
    english = factor(english)
  )




