Getting better embeddings
Data quality and quantity are the most important factors. For word2vec, aim for at least 10 million words; 100 million is better. Clean your data carefully:
corpus_clean &lt;- raw_text |&gt;
  iconv(to = "UTF-8", sub = "") |&gt;      # Fix encoding
  tolower() |&gt;
  str_replace_all("http\\S+", " ") |&gt;   # Remove URLs
  str_replace_all("\\d+", " ") |&gt;       # Handle numbers
  str_replace_all("[^[:alnum:][:space:]]", " ") |&gt;  # Remove punctuation
  str_replace_all("\\s+", " ") |&gt;
  str_trim()

Evaluating embeddings
Intrinsic evaluation measures how well embeddings capture human semantic judgements:
# Word similarity datasets: WordSim-353, SimLex-999
evaluate_similarity &lt;- function(model, test_pairs) {
  model_scores &lt;- sapply(1:nrow(test_pairs), function(i) {
    predict(model,
            newdata = c(test_pairs$word1[i], test_pairs$word2[i]),
            type    = "similarity")
  })
  cor(model_scores, test_pairs$human_score, method = "spearman")
}
Extrinsic evaluation measures performance on a downstream task (text classification, NER, sentiment analysis). This is generally more informative for applied research because it directly measures whether the embeddings are useful for your specific application.

Text cleaning in R
The stringr package provides a consistent, readable interface for string manipulation. Here is a systematic cleaning pipeline:


Code
library(stringr)
library(dplyr)

clean_text &lt;- function(text) {
  text |&gt;
    # Remove HTML tags
    str_remove_all("&lt;[^&gt;]+&gt;") |&gt;
    # Remove URLs
    str_remove_all("https?://\\S+") |&gt;
    # Remove email addresses
    str_remove_all("\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}\\b") |&gt;
    # Standardise line endings (Windows CRLF → Unix LF)
    str_replace_all("\r\n", "\n") |&gt;
    # Remove excessive blank lines (3+ consecutive newlines → 2)
    str_replace_all("\n{3,}", "\n\n") |&gt;
    # Collapse multiple spaces to one
    str_replace_all("[ \t]{2,}", " ") |&gt;
    # Remove leading/trailing whitespace per line
    str_replace_all("(?m)^[ \t]+|[ \t]+$", "") |&gt;
    # Final trim
    str_trim()
}

# Apply to the corpus data frame
corpus_df &lt;- corpus_df |&gt;
  mutate(
    text_raw     = text,           # keep original
    text_cleaned = clean_text(text)
  )

# Sanity check: compare a sample
cat("=== ORIGINAL (first 300 chars) ===\n")
cat(substr(corpus_df$text_raw[1], 1, 300), "\n\n")
cat("=== CLEANED (first 300 chars) ===\n")
cat(substr(corpus_df$text_cleaned[1], 1, 300), "\n")

Duplicate detection
Near-duplicate texts inflate corpus frequencies and bias results. After cleaning, always check for duplicates:


Code
library(dplyr)
library(stringr)

# Exact duplicates: same cleaned text
corpus_df &lt;- corpus_df |&gt;
  mutate(text_hash = digest::digest(text_cleaned, algo = "md5"))

exact_dupes &lt;- corpus_df |&gt;
  group_by(text_hash) |&gt;
  filter(n() &gt; 1) |&gt;
  arrange(text_hash)

if (nrow(exact_dupes) &gt; 0) {
  cat("Exact duplicates found:", nrow(exact_dupes), "files\n")
  print(exact_dupes[, c("filename", "text_hash")])
}

# Near-duplicates: very high character overlap
# A simple heuristic: files where the first 500 characters are identical
corpus_df &lt;- corpus_df |&gt;
  mutate(start_500 = substr(text_cleaned, 1, 500))

near_dupes &lt;- corpus_df |&gt;
  group_by(start_500) |&gt;
  filter(n() &gt; 1 & nchar(start_500) &gt; 100)

if (nrow(near_dupes) &gt; 0) {
  cat("Possible near-duplicates found:", nrow(near_dupes), "files\n")
  print(near_dupes[, c("filename")])
}

